import{_ as e,o as i,c as a,ae as n}from"./chunks/framework.Dh1jimFm.js";const h=JSON.parse('{"title":"Editing & Confirming","description":"","frontmatter":{},"headers":[],"relativePath":"editor/editing-confirming.md","filePath":"editor/editing-confirming.md"}'),r={name:"editor/editing-confirming.md"};function o(l,t,s,d,g,m){return i(),a("div",null,t[0]||(t[0]=[n('<h1 id="editing-confirming" tabindex="-1">Editing &amp; Confirming <a class="header-anchor" href="#editing-confirming" aria-label="Permalink to &quot;Editing &amp; Confirming&quot;">​</a></h1><p>Translate by editing the <strong>Target</strong> column in the grid.</p><h2 id="editing" tabindex="-1">Editing <a class="header-anchor" href="#editing" aria-label="Permalink to &quot;Editing&quot;">​</a></h2><ul><li>Double-click a Target cell and type your translation.</li><li>Use standard editing shortcuts (undo/redo, copy/paste, find/replace).</li></ul><h3 id="multi-line-target-text" tabindex="-1">Multi-line target text <a class="header-anchor" href="#multi-line-target-text" aria-label="Permalink to &quot;Multi-line target text&quot;">​</a></h3><ul><li>Use <strong>Shift+Enter</strong> to insert a line break inside the cell.</li></ul><h2 id="confirming-segments" tabindex="-1">Confirming segments <a class="header-anchor" href="#confirming-segments" aria-label="Permalink to &quot;Confirming segments&quot;">​</a></h2><p>Confirming matters for many workflows, especially when exporting back to a CAT tool.</p><p>Typical workflow:</p><ol><li>Translate (manual or AI)</li><li>Review the target text</li><li>Confirm the segment</li></ol><h3 id="confirm-shortcuts" tabindex="-1">Confirm shortcuts <a class="header-anchor" href="#confirm-shortcuts" aria-label="Permalink to &quot;Confirm shortcuts&quot;">​</a></h3><ul><li><strong>Ctrl+Enter</strong>: confirm the current segment (or all selected segments) and move to the next unconfirmed segment.</li><li><strong>Ctrl+Shift+Enter</strong>: confirm all selected segments.</li></ul><p>You can also confirm by setting the segment <strong>Status</strong> dropdown to a confirmed status.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If you plan to reimport into a CAT tool, avoid merging/splitting content across segments.</p></div><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./segment-statuses.html">Segment Statuses</a> — full reference for workflow statuses, match origins, and how they map to Trados and memoQ</li><li><a href="./translation-grid.html">The Translation Grid</a></li><li><a href="./find-replace.html">Find &amp; Replace</a></li><li><a href="./../qa/tag-validation.html">Tag Validation</a></li></ul>',16)]))}const f=e(r,[["render",o]]);export{h as __pageData,f as default};
